import argparse
import os
import sys


CODE_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if CODE_ROOT not in sys.path:
    sys.path.insert(0, CODE_ROOT)

from src.config import OUTPUT_DIR
from src.ranking import (
    evaluate_rankings,
    extract_genes,
    read_gene_list,
    read_prediction_table,
)


def choose_panel(spec, available_genes):
    """Read the fixed candidate panel generated by script 05."""
    text = str(spec or "").strip()
    if not text or text.lower() in {"all", "auto"}:
        raise ValueError(
            "Script 06 requires --candidate-genes to point to the panel file "
            "generated by script 05."
        )
    if not os.path.isfile(text):
        raise FileNotFoundError(f"Candidate-gene panel file not found: {text}")

    available = list(dict.fromkeys(str(gene) for gene in available_genes))
    available_set = set(available)
    requested = read_gene_list(text)
    selected = [gene for gene in requested if gene in available_set]
    if not selected:
        raise ValueError("The candidate panel has no genes in the prediction file.")
    return selected


def write_gene_file(path, genes):
    with open(path, "w", encoding="utf-8") as handle:
        for gene in genes:
            handle.write(f"{gene}\n")


def main():
    parser = argparse.ArgumentParser(
        description="Process patient-level ranking with GPS scores."
    )
    parser.add_argument(
        "--pred-file",
        default=None,
        help="02 prediction TSV; defaults to the current prediction output.",
    )
    parser.add_argument(
        "--candidate-genes",
        required=True,
        help="One-gene-per-line panel file generated by script 05.",
    )
    parser.add_argument("--outdir", default=None, help="Project output root.")
    args = parser.parse_args()

    project_output = os.path.abspath(args.outdir or OUTPUT_DIR)
    step_dir = os.path.join(project_output, "06_patient_level_pred_drv")
    output_dir = os.path.join(step_dir, "output")
    os.makedirs(output_dir, exist_ok=True)

    pred_file = os.path.abspath(
        args.pred_file
        or os.path.join(
            project_output,
            "02_model_optimization",
            "output",
            "gps_predictions_logcv.tsv",
        )
    )
    print(f"Loading predictions: {pred_file}")
    predictions = read_prediction_table(pred_file)
    available_genes = extract_genes(predictions)
    if not available_genes:
        raise ValueError("No score/carrier gene pairs were found.")

    panel = choose_panel(args.candidate_genes, available_genes)
    print(f"Processing {len(panel)} panel genes across {len(predictions)} samples...")
    rank_samples = evaluate_rankings(predictions, panel, show_progress=True)

    candidate_path = os.path.join(output_dir, "patient_level_candidate_genes.txt")
    rank_samples_path = os.path.join(output_dir, "patient_level_predication.tsv")
    rank_columns = [
        "Sample ID",
        "is_panel_carrier_sample",
        "n_rankable_panel_genes",
        "n_missing_panel_scores",
        "top1_gene",
        "top1_score",
        "true_carrier_genes",
        "true_carrier_scores",
        "best_true_rank",
    ]
    rank_samples = rank_samples[rank_columns].copy()
    rank_samples = rank_samples[rank_samples["best_true_rank"].notna()].copy()
    write_gene_file(candidate_path, panel)
    rank_samples.to_csv(rank_samples_path, sep="\t", index=False)

    print(f"Patient-level results: {output_dir}")


if __name__ == "__main__":
    main()
